Given an array arr[], the task is to find the largest subset from array that contain elements which are Fibonacci numbers.Examples : Input: arr[] = [1, 4, 3, 9, 10, 13, 7]Output: [1, 3, 13]Explanation: The output three numbers are the only Fibonacci numbers in array.Input: arr[] = [0, 2, 8, 5, 2, 1, 4, 13, 23]Output: [0, 2, 8, 5, 2, 1, 13]Explanation: The output numbers are the only Fibonacci numbers in array.Try It YourselfTable of Content[Naive Approach] Using Hash Set – O(n) Time and O(n) Space[Expected Approach] Using Mathematical Formulae – O(n log m) Time and O(1) Space[Naive Approach] Using Hash Set – O(n) Time and O(n) SpaceA simple solution is to use a Hash Set. Firstly traverse the array to find the max element in the array,  Then generate all the Fibonacci numbers smaller than max element and store them in Hash Set. Now traverse the array and check if that element is there in the Hash set or not. If Yes, put it in the result array.
            C++

    // C++ program to find largest Fibonacci subset
// Using Hash set
#include <iostream>
#include <vector>
#include <unordered_set>
#include <algorithm>
using namespace std;

// Prints largest subset of an array whose
// all elements are fibonacci numbers
vector<int> findFibSubset(vector<int> &arr){
    int n = arr.size();

    // Find maximum element in arr[]
    int max = *max_element(arr.begin(), arr.end());

    // Generate all Fibonacci numbers till
    // max and store them in hash.
    int a = 0, b = 1;
    unordered_set<int> st;
    st.insert(a);
    st.insert(b);
    while (b < max){
        int c = a + b;
        a = b;
        b = c;
        st.insert(b);
    }
    vector<int> res;

    // Now iterate through all numbers and
    // quickly check for Fibonacci using hash.
    for (int i = 0; i < n; i++)
        if (st.find(arr[i]) != st.end())
            res.push_back(arr[i]);

    return res;
}

// Driver code
int main() {
    vector<int> arr = {4, 2, 8, 5, 20, 1, 40, 13, 23};
   	vector<int> res= findFibSubset(arr);
    for (int i = 0; i < res.size(); i++)
      	cout<< res[i] << " ";
    cout << endl;
    return 0;
}


